    'fc.help_body' => 'Gestisce i codici rapidi composti dal telefono (come <code>*78</code>): Non disturbare (DND), Inoltro di chiamata, Risposta per assente di gruppo/diretta, Ascolto chiamata, Accesso/uscita dalla coda (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), Pausa / ripresa in coda (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
    'fc.help_body2' => 'Per ogni codice è possibile modificare il <strong>codice</strong> (i codici normali devono iniziare con <code>*</code>, quelli con un parametro variabile con <code>_*</code>) e <strong>quali ruoli possono usarlo</strong> (vuoto = tutti). Il comportamento (cosa fa) è fisso — non è possibile aggiungere nuovi tipi di comportamento, si possono solo modificare questi codici.',
