    'asterisk_settings.rtp_section_title' => 'Impostazioni RTP (media)',
    'asterisk_settings.rtp_help_body' => 'Controlla quale intervallo di porte trasporta l\'audio (RTP) e se Asterisk rifiuta l\'audio proveniente da un\'origine inattesa. Questo file (<code>/etc/asterisk/rtp.conf</code>) è ora generato dal pannello; le modifiche manuali sul server vengono perse al successivo "Applica".',
    'asterisk_settings.field_rtp_start' => 'Porta iniziale RTP',
    'asterisk_settings.rtp_start_help' => 'Inizio dell\'intervallo di porte riservato ai flussi audio. Ogni chiamata simultanea utilizza porte di questo intervallo.',
    'asterisk_settings.field_rtp_end' => 'Porta finale RTP',
    'asterisk_settings.rtp_end_help' => 'Fine dell\'intervallo. coturn (relay TURN) usa 13479-14999 — una sovrapposizione compromette l\'audio WebRTC e viene rifiutata al salvataggio.',
    'asterisk_settings.field_rtp_strict' => 'RTP rigoroso (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Se abilitato, Asterisk scarta silenziosamente l\'audio proveniente da qualsiasi origine diversa dall\'indirizzo/porta remota appresa (protezione dagli attacchi). Se il PBX remoto invia i media da una porta inattesa, si verifica un guasto silenzioso "senza audio" senza traccia nei log — può essere disattivato temporaneamente per la diagnosi.',
    'asterisk_settings.rtp_strict_yes' => 'Abilitato (consigliato)',
    'asterisk_settings.rtp_strict_no' => 'Disabilitato (per la diagnosi)',
    'asterisk_settings.rtp_restart_warning' => 'L\'impostazione RTP rigoroso ha effetto con "Applica". Una modifica dell\'INTERVALLO DI PORTE, invece, richiede un riavvio completo di Asterisk — il pool di porte viene allocato una sola volta al caricamento del modulo.',
    'asterisk_settings.udptl_section_title' => 'Impostazioni T.38 UDPTL (media fax)',
    'asterisk_settings.udptl_help_body' => 'Definisce gli intervalli di porte UDP e i parametri di correzione degli errori (FEC / Checksum) per i pacchetti fax T.38 (UDPTL). Questo file (<code>/etc/asterisk/udptl.conf</code>) è gestito dinamicamente.',
    'asterisk_settings.field_udptl_start' => 'Porta iniziale UDPTL',
