    'trunks.field_connection_mode' => 'Modalità di connessione',
    'trunks.connection_mode_ip' => 'Basata su IP (il peer ha un IP statico)',
    'trunks.connection_mode_register' => 'Registrazione in ingresso (il peer si registra presso di noi)',
    'trunks.connection_mode_help' => 'Basata su IP: il peer è identificato dal suo indirizzo IP e il suo contatto è mantenuto statico — la modalità consigliata per un peer con IP fisso sulla stessa rete. Registrazione in ingresso: il peer ci invia un SIP REGISTER e il suo indirizzo viene appreso da tale registrazione. Questa modalità richiede nome utente e password; il peer li usa per autenticare sia la registrazione sia le chiamate.',
    'trunks.connection_mode_warning' => 'Il passaggio alla modalità di registrazione rimuove il contatto statico: non potremo chiamare quel trunk FINCHÉ il peer non si registra presso di noi. Effettui questa modifica in coordinamento con l\'impostazione di registrazione sul lato del peer.',
