    'sound_packs.title' => 'Pacchetti audio ufficiali di Asterisk',
    'sound_packs.help_title' => 'Pacchetti audio di Asterisk',
    'sound_packs.help_body' => 'Scarica e installa i messaggi di sistema e la musica di attesa ufficiali di Asterisk da <code>downloads.asterisk.org</code>. Ogni pacchetto corrisponde a una lingua in un formato; Asterisk riproduce il formato corrispondente al codec della chiamata e altrimenti transcodifica (g722 per G.722, ulaw/alaw per gli operatori).<br>- <strong>Core:</strong> messaggi di sistema, cifre, segreteria telefonica. <strong>Extra:</strong> messaggi aggiuntivi; deve essere prima installato il pacchetto core della stessa lingua.<br>- <strong>Musica di attesa (opsound):</strong> installata in <code>/var/lib/asterisk/moh/opsound</code>; per riprodurla, crei una classe MOH denominata <strong>opsound</strong> nella scheda Musica di attesa.<br>- <strong>Türkçe (AiPBX):</strong> i messaggi turchi propri di AiPBX (release GitHub, verificati SHA256); la lingua predefinita è il turco, quindi rimuoverli rende muti i messaggi di sistema. La rimozione elimina solo i file installati dal pacchetto.',
