    'ms_teams.guide_intro' => 'AiPBX può comunicare con Microsoft Teams su due livelli diversi:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / trunk SIP):',
    'ms_teams.guide_dr_desc' => 'Consente agli utenti Teams di effettuare e ricevere chiamate interne ed esterne direttamente dal tastierino di Teams desktop/mobile. Richiede TLS (porta 5061), SRTP e un certificato SSL pubblico valido (es. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhook e notifiche sui canali:',
