    'system_update.help_title' => 'Come funziona l\'aggiornamento?',
    'system_update.help_body' => 'L\'aggiornamento esegue prima il backup del database, delle impostazioni e della configurazione di Asterisk, poi installa la nuova versione e verifica che tutto funzioni. Se qualcosa non va, torna automaticamente alla versione precedente. Durante l\'aggiornamento Asterisk viene riavviato: le chiamate in corso vengono interrotte, quindi non parte mentre ci sono chiamate attive. Può essere eseguito anche sul server: <code>sudo aipbx-update</code>',
