    'certificates.header_title' => 'Certificato TLS',
    'certificates.help_title' => 'Guida ai certificati',
    'certificates.help_body' => 'Il portale (HTTPS), WebRTC TURNS e SIP-TLS/WSS condividono un unico certificato; le modifiche qui vengono applicate insieme ad Apache, coturn e Asterisk. <b>Let\'s Encrypt</b> è gratuito e si rinnova da solo; il dominio deve puntare a questo server e la porta 80 deve essere raggiungibile da internet. Se la sua organizzazione dispone di un certificato, lo <b>carichi</b> (PEM o PFX); i certificati caricati non si rinnovano automaticamente, ne carichi uno nuovo prima della scadenza. Con un certificato <b>autofirmato</b> i browser mostrano un avviso e TURNS non funziona nei browser: le chiamate WebRTC dietro firewall potrebbero non avere audio.',
