    'sidebar.item_queue_reports' => 'Centro report code',
    'queue_reports.title' => 'Centro report code',
    'queue_reports.help_title' => 'Guida ai report delle code',
    'queue_reports.help_body' => 'Ogni chiamata che entra in una coda viene conteggiata una sola volta. <b>Risposte</b>: connesse a un operatore. <b>Perse</b>: il chiamante ha riagganciato durante l\'attesa o la coda è andata in timeout. <b>Abbandono breve</b>: riagganciata entro %d secondi; esclusa dal livello di servizio. <b>Livello di servizio</b>: chiamate risposte entro l\'obiettivo, su tutte le chiamate tranne gli abbandoni brevi. <b>ASA</b>: attesa media delle chiamate risposte. <b>AHT</b>: durata media della conversazione. <b>Tasso di risposta</b> (operatore): quanto spesso l\'operatore ha risposto quando la coda lo ha fatto squillare. <b>Richiamata</b>: una chiamata persa è considerata risolta quando il suo numero è stato successivamente chiamato da un interno, oppure ha richiamato e ha ricevuto risposta. I dati provengono dal queue log di Asterisk; il report può essere scaricato in PDF o Excel.',
