    'ai_tts.title' => 'Cloud TTS (sintesi vocale)',
    'ai_tts.help_title' => 'Guida a Cloud TTS',
    'ai_tts.help_body' => 'Trasforma il testo in voce naturale tramite servizi cloud (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Ascolti il risultato, lo scarichi in MP3 o lo salvi come <b>annuncio</b> con un clic: viene convertito nel formato di Asterisk (WAV 8 kHz) e aggiunto a Suoni &amp; annunci per IVR, rotte in ingresso e condizioni orarie (attivo dopo Applica). <b>Questi servizi sono a pagamento</b> e fatturano per carattere; ogni sintesi viene conservata nella cronologia con il numero di caratteri. Le chiavi di accesso si ottengono dalla console di ciascun fornitore, sono memorizzate cifrate e non vengono più mostrate nella pagina.',
