    'ai_tts.tab_providers' => 'Fornitori',
    'ai_tts.providers_text' => 'Inserisca i dati di accesso dei servizi che desidera usare. Le chiavi segrete sono memorizzate cifrate; lasci vuota una chiave per mantenere quella memorizzata.',
