    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: abiliti "Cloud Text-to-Speech API"; usi una chiave JSON di un account di servizio (IAM → Service Accounts → Keys → JSON) o una chiave API. Fino a %s caratteri per richiesta; i testi più lunghi vengono suddivisi.',
    'ai_tts.provider_hint_polly' => 'In AWS IAM crei una chiave di accesso per un utente che disponga solo di "polly:SynthesizeSpeech" e "polly:DescribeVoices". Fino a %s caratteri per richiesta.',
    'ai_tts.provider_hint_azure' => 'Crei una risorsa "Speech" nel portale Azure; chiave e area geografica (es. westeurope) si trovano nella pagina "Keys and Endpoint". Fino a %s caratteri per richiesta.',
