    'push.help_intro' => 'Il softphone mobile AI PBX ha un\'<strong>architettura di notifica a livelli</strong>:',
    'push.help_layer0' => '<strong>Livello 0 (nessuna dipendenza - predefinito):</strong> una connessione WSS persistente, un servizio in primo piano <code>specialUse</code> compatibile con Android 15 e un watchdog <code>AlarmManager</code> resistente a Doze che lo riattiva. Non serve alcun servizio esterno; le chiamate arrivano anche quando il dispositivo è inattivo o lo schermo è spento.',
    'push.help_layer1' => '<strong>Livello 1 (opzionale - Google FCM):</strong> una garanzia di risveglio aggiuntiva sui dispositivi OEM con restrizioni aggressive della batteria (Xiaomi, Huawei...) o quando l\'utente ha chiuso l\'app scorrendo. <em>Si attiva solo quando l\'interno non ha una registrazione SIP attiva, quindi gli interni registrati non subiscono ritardi.</em>',
