    'mailtpl.invite_new.subject' => '[{brand}] Il Suo account è stato creato - imposti la password',
    'mailtpl.invite_new.body' => '<p>Gentile {name},</p><p>il Suo account sul centralino <strong>{brand}</strong> è pronto. Per accedere, imposti la password con il pulsante qui sotto.</p>{account_details}{reset_button}<p>Se il pulsante non funziona, apra questo link: {reset_link}</p>{mobile_section}<p><em>Il link per la password è valido 48 ore e funziona una sola volta. Se non si aspettava questa e-mail, contatti l’amministratore di sistema.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Il Suo link di accesso e password',
    'mailtpl.invite.body' => '<p>Gentile {name},</p><p>ecco un nuovo link per impostare la password di <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Se il pulsante non funziona, apra questo link: {reset_link}</p>{mobile_section}<p><em>Il link per la password è valido 48 ore e funziona una sola volta. Se non lo ha richiesto, contatti l’amministratore di sistema.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Reimposti la password',
    'mailtpl.password_reset.body' => '<p>Gentile {name},</p><p>è stata richiesta la reimpostazione della password per il Suo account <strong>{username}</strong>.</p>{reset_button}<p>Se il pulsante non funziona, apra questo link: {reset_link}</p><p><em>Il link è valido 30 minuti. Se non lo ha richiesto, ignori questa e-mail; la password resta invariata.</em></p>',
    'mailtpl.voicemail.subject' => 'Nuovo messaggio vocale da {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Gentile {name},</p><p>ha un nuovo messaggio nella casella vocale <strong>{mailbox}</strong>.</p><ul><li><strong>Da:</strong> {caller}</li><li><strong>Ricevuto:</strong> {date}</li><li><strong>Durata:</strong> {duration}</li></ul><p>Se la registrazione è allegata, può ascoltarla direttamente qui. Può anche ascoltarla nel portale ({portal_link}) o componendo *97.</p>',
    'mailtpl.fax_received.subject' => 'Nuovo fax ricevuto - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>È stato ricevuto un nuovo fax.</p><ul><li><strong>Unità:</strong> {department}</li><li><strong>Numero di fax:</strong> {did}</li><li><strong>Da:</strong> {caller}</li><li><strong>Pagine:</strong> {pages}</li><li><strong>Ricevuto:</strong> {date}</li></ul><p>Il fax è allegato in PDF se l’opzione è attiva. Tutti i fax si trovano nella posta in arrivo fax: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Fax consegnato a {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Il Suo fax è stato consegnato.</p><ul><li><strong>A:</strong> {destination}</li><li><strong>Pagine:</strong> {pages}</li><li><strong>Ora:</strong> {date}</li></ul><p>Fax inviati: {portal_link}</p>',
    'mailtpl.fax_failed.subject' => 'Fax NON consegnato a {destination} (#{fax_id})',
    'mailtpl.fax_failed.body' => '<p>Non è stato possibile consegnare il Suo fax.</p><ul><li><strong>A:</strong> {destination}</li><li><strong>Pagine:</strong> {pages}</li><li><strong>Ora:</strong> {date}</li><li><strong>Motivo:</strong> {error}</li></ul><p>Può inviarlo di nuovo dal portale: {portal_link}</p>',
    'mailtpl.test.subject' => 'E-mail di prova {brand} ({date})',
    'mailtpl.test.body' => '<p>Questa è un’e-mail di prova da <strong>{brand}</strong>. Se riesce a leggerla, l’invio delle e-mail funziona.</p><ul><li><strong>Inviata:</strong> {date}</li><li><strong>Da:</strong> {from_name} &lt;{from_address}&gt;</li><li><strong>A:</strong> {to}</li><li><strong>Server:</strong> {host}</li></ul>',
