    'storage.help_title' => 'Dove vengono conservati i file della chat',
    'storage.help_body' => '<p>Gli allegati della chat, le loro miniature e le immagini dei gruppi vengono salvati per impostazione predefinita sul disco del server (<code>/var/lib/aipbx/chat_files</code>). Con uno storage compatibile S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) finiscono invece in un bucket e i file di grandi dimensioni restano fuori dal PBX.</p><p>I download continuano a passare dal servizio chat, quindi solo i partecipanti di una chat possono aprirne i file; il bucket può restare privato. I file salvati prima del passaggio continuano a essere serviti dal disco finché non li sposta. Le impostazioni del bucket vengono verificate prima del salvataggio.</p><p>Registrazioni delle chiamate, segreteria telefonica e fax restano sul disco locale.</p>',
