    'netsvc.help_title' => 'Servizi di rete',
    'netsvc.help_body' => 'I telefoni da scrivania trovano da soli il server di provisioning quando il server DHCP ne distribuisce l\'indirizzo (opzione 66). DHCP e TFTP si attivano separatamente. Con il <strong>server DHCP</strong> disattivato resta il vostro server DHCP: imposti lì le opzioni elencate sotto. Se è attivo, AiPBX distribuisce indirizzi su un\'interfaccia o VLAN. Il <strong>server TFTP</strong> fornisce i file di avvio e il firmware caricati. La configurazione di ogni telefono (con la password SIP) viene sempre fornita via HTTPS, mai via TFTP.',
