    'web_widgets.help_title' => 'Widget di chiamata per siti web e modulo di richiamata',
    'web_widgets.help_body' => 'Un widget aggiunge un pulsante "Chiamaci" a qualsiasi sito web. I visitatori parlano con voi dal browser tramite WebRTC, oppure lasciano il proprio numero e il PBX li richiama. Incolli il codice di una riga nel sito web (o nel plugin WordPress) e, dopo il salvataggio, prema <strong>Applica</strong>.',
    'web_widgets.help_number' => 'Numero:',
    'web_widgets.help_number_desc' => 'Un widget entra nel PBX come un trunk. Il suo numero è il DID di queste chiamate nei report e nei CDR; il visitatore non sceglie mai dove va la chiamata.',
    'web_widgets.help_security' => 'Sicurezza:',
    'web_widgets.help_security_desc' => 'Solo i siti web consentiti possono usare il widget. Ogni chiamata richiede un token monouso e i limiti (per IP, al giorno, chiamate simultanee, durata della chiamata) si applicano a ogni richiesta. Ogni richiesta viene registrata qui sotto.',
    'web_widgets.help_callback' => 'Richiamata:',
    'web_widgets.help_callback_desc' => 'Il PBX chiama il visitatore tramite la rotta in uscita scelta e, quando risponde, lo inoltra alla destinazione. Vengono chiamati solo i numeri che iniziano con i prefissi consentiti, ed è obbligatorio un limite giornaliero.',
    'web_widgets.help_wordpress' => 'WordPress:',
